n = int(input())

# Dictionary to store names by their starting and ending letters
names_by_start = {}
names_by_end = {}

# Parse input
for i in range(n):
    name = input().strip()
    start = name[0]
    end = name[-1]
    length = len(name)

    # Store name by its start letter
    if start not in names_by_start:
        names_by_start[start] = []
    names_by_start[start].append((end, length))

    # Store name by its end letter
    if end not in names_by_end:
        names_by_end[end] = []
    names_by_end[end].append((start, length))

# DP: dp[c] = longest path ending at node c
# Initialize to 0 for all nodes
# We'll use ord('a') to 25 for convenience
# We'll only update dp for nodes that have names

dp = {chr(c): 0 for c in range(ord('a'), ord('z') + 1)}

# Process names in order
for start in names_by_start:
    for end, length in names_by_start[start]:
        # Update dp for end node
        # We can extend any existing path ending at start
        if dp[start] > 0:
            dp[end] = max(dp[end], dp[start] + length)

        # We can also start a new sequence at this name
        dp[end] = max(dp[end], length)

# Find the longest cycle
max_cycle_length = 0
for c in dp:
    if dp[c] > 0:
        # Check if there's a name that starts with c and ends with c
        if names_by_start.get(c) and any(end == c for end, length in names_by_start[c]):
            max_cycle_length = max(max_cycle_length, dp[c])

print(max_cycle_length)
