def solve():
    n, m = map(int, input().split())
    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        a, b = map(int, input().split())
        graph[a].append(b)
        graph[b].append(a)

    visited = [False] * (n + 1)
    result = 0

    def find_component_size(start):
        # Use BFS to find component size
        from collections import deque
        queue = deque([start])
        visited[start] = True
        size = 0
        while queue:
            node = queue.popleft()
            size += 1
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return size

    for i in range(1, n + 1):
        if not visited[i]:
            component_size = find_component_size(i)
            if component_size == 3:
                result += 1
            elif component_size > 3:
                result += 2

    print(result)

solve()
