def construct_table(n, m):
    table = [[0 for _ in range(m)] for _ in range(n)]

    # Place 1s everywhere except the diagonal
    for i in range(n):
        for j in range(m):
            if i != j:
                table[i][j] = 1

    # Place a large number on the diagonal
    for i in range(n):
        if i < m:
            table[i][i] = 100000000

    return table

def print_table(table):
    for row in table:
        print(" ".join(map(str, row)))

def solve():
    n, m = map(int, input().split())
    table = construct_table(n, m)
    print_table(table)

solve()
