def construct_table(n, m):
    table = [[0 for _ in range(m)] for _ in range(n)]

    # Fill the table with 1s
    for i in range(n):
        for j in range(m):
            if i < n and j < m:
                table[i][j] = 1

    # Special case: 1x2 table
    if n == 1 and m == 2:
        table[0][0] = 3
        table[0][1] = 4

    return table

def print_table(table):
    for row in table:
        print(" ".join(map(str, row)))

