        t, q = map(int, input().split())
        tasks.append((t, q))

    # Sort by interest descending, time ascending
    tasks.sort(key=lambda x: (-x[1], x[0]))

    total_interest = 0

    # Tree depth structure: tree[d] = number of tasks at depth d
    tree = {}  # dictionary for flexible indexing

    for t, q in tasks:
        # Find the minimum depth where we can place this task
        placed = False

        # Try to place at depth 0 (root depth)
        if 0 + t <= T:
            # Depth 0 can have at most 1 leaf
            if len(tree) == 0 or len(tree.get(0, [])) == 0:
                tree[0] = [t]
                total_interest += q
                placed = True

        if not placed:
            # Try to place at depth 1
            if 1 + t <= T:
                if len(tree) < 1 or len(tree.get(1, [])) == 0:
                    tree[1] = [t]
                    total_interest += q
                    placed = True

        if not placed:
            # Try to place at depth 2
            if 2 + t <= T:
                if len(tree) < 2 or len(tree.get(2, [])) == 0:
                    tree[2] = [t]
                    total_interest += q
                    placed = True

        if not placed:
            break

    print(total_interest)

solve()

