def find_adjacent_vertices(n, degrees, xor_sums):

    # Start from vertex 0
    visited = [False] * n
    edges = []

    # Find a starting point
    for v in range(n):
        if degrees[v] == 0:
            # This vertex is isolated, we can ignore
            continue

        # Start DFS or BFS from this vertex
        stack = [v]
        visited[v] = True

        while stack:
            current = stack.pop()

            # For the current vertex, find all neighbors
            # Neighbors are vertices where current is in their XOR sum
            neighbors = []
            for neighbor in range(n):
                if neighbor == current:
                    continue
                if (xor_sums[neighbor] & (1 << current)) != 0:
                    neighbors.append(neighbor)

            # Check if we have found all neighbors
            if len(neighbors) == degrees[current]:
                # We found all neighbors
                for neighbor in neighbors:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
                        edges.append((min(current, neighbor), max(current, neighbor)))
            else:
                # Not all neighbors found, continue
                pass

    return edges

