def can_cut(s, i, l):
    """Check if character at position i (1-indexed) can be cut with mirror length l"""
    n = len(s)
    if i - l >= 0 and i + l < n:
        # Check mirror symmetry
        for k in range(1, l + 1):
            if s[i - l + k] != s[i + l - k]:
                return False
        return True
    return False


def grundy_numbers(s):
    """Calculate Grundy numbers for all lengths"""
    n = len(s)
    grundy = [0] * (n + 1)

    # Base case: length 1 has no moves
    grundy[1] = 0

    # Calculate grundy numbers for lengths 2 to n
    for length in range(2, n + 1):
        reachable = set()

        # For each possible cut position in this length
        for pos in range(1, length + 1):
            # Check if position pos can be cut
            for l in range(1, length // 2 + 1):
                if can_cut(s, pos, l):
                    # Calculate the XOR of Grundy numbers of the three new pieces
                    len_left = pos - l
                    len_middle = 1
                    len_right = length - pos + l
                    reachable.add(grundy[len_left] ^ grundy[len_middle] ^ grundy[len_right])
                    break  # Only need the first valid move at this position

        # Grundy number is mex of reachable values
        mex = 0
        while mex in reachable:
            mex += 1
        grundy[length] = mex

    return grundy


def solve(s):
    """Solve the game"""
    n = len(s)
    grundy = grundy_numbers(s)

    # If the Grundy number of the whole string is non-zero, first player wins
    if grundy[n] != 0:
        # Find minimal winning move
        for pos in range(1, n + 1):
            for l in range(1, n // 2 + 1):
                if can_cut(s, pos, l):
                    return f"First\n{pos}"
    return "Second"

if __name__ == "__main__":
    s = input().strip()
    print(solve(s))
