import sys

def solve():
    n = int(sys.stdin.readline())

    # dp[start][end] = max total length of sequence starting with start and ending with end
    # We'll use a regular dict for dp
    dp = {}

    for _ in range(n):
        line = sys.stdin.readline().strip()

        if not line:
            continue

        start_char = line[0]
        end_char = line[-1]
        name_len = len(line)

        # Make a copy of current dp
        new_dp = {}
        for s in dp:
            for e in dp[s]:
                new_dp[(s, e)] = dp[(s, e)]

        # Try to extend existing sequences
        for (start, end), length in dp.items():
            # After adding this name, new start = start, new end = end_char
            new_dp[(start, end_char)] = max(new_dp.get((start, end_char), 0), length + name_len)

        # Try to start a new sequence with this name
        new_dp[(start_char, end_char)] = max(new_dp.get((start_char, end_char), 0), name_len)

        dp = new_dp

    # Find the maximum cyclic sequence (start == end)
    max_len = 0
    for (start, end), length in dp.items():
        if start == end and length > max_len:
            max_len = length

    print(max_len)

solve()
