import heapq

def dijkstra(start, end, max_day, flights):
    """Find minimum cost from start to end with departure/arrival constraints"""
    dist = {city: float('inf') for city in range(max_day + 1)}
    dist[start] = 0

    # State: (cost, day, city)
    pq = [(0, start, start)]

    while pq:
        cost, day, city = heapq.heappop(pq)

        if city == end:
            return cost

        if cost > dist[day]:
            continue

        # Check all flights from this city on this day
        for flight in flights.get(day, []):
            if flight[0] == 0:  # Metropolis to other city
                to_city = flight[1]
                dep_day = day + 1

                # Departure day must be ≥ max_day
                if dep_day >= max_day:
                    if cost + flight[3] < dist[dep_day]:
                        dist[dep_day] = cost + flight[3]
                        heapq.heappush(pq, (cost + flight[3], dep_day, to_city))
            else:  # Other city to Metropolis
                from_city = flight[2]
                arr_day = day

                # Arrival day must be ≤ max_day
                if arr_day <= max_day:
                    if cost + flight[3] < dist[arr_day]:
                        dist[arr_day] = cost + flight[3]
                        heapq.heappush(pq, (cost + flight[3], arr_day, from_city))

    return float('inf')

n, m, k = map(int, input().split())
flights = {}

for _ in range(m):
    d, f, t, c = map(int, input().split())
    if d not in flights:
        flights[d] = []
    flights[d].append((f, t, c))

# Find minimum cost for each city to Metropolis with arrival ≤ 0
arrival_cost = []
for i in range(1, n + 1):
    cost = dijkstra(i, 0, 0, flights)
    arrival_cost.append(cost)
    print(f"City {i} arrival cost: {cost}")

# Find minimum cost for Metropolis to each city with departure ≥ k+1
departure_cost = []
for i in range(1, n + 1):
    cost = dijkstra(0, i, k + 1, flights)
    departure_cost.append(cost)
    print(f"City {i} departure cost: {cost}")

# Sum costs
total_cost = sum(arrival_cost) + sum(departure_cost)

if any(cost == float('inf') for cost in arrival_cost + departure_cost):
    print(-1)
else:
    print(total_cost)
