    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    # Initial elements
    a = []
    for _ in range(n):
        a.append(int(next(it)))

    # Coordinate compression
    sorted_vals = sorted(set(a))
    compressed = {v: i+1 for i, v in enumerate(sorted_vals)}
    max_val = len(sorted_vals)

    # BIT implementation
    class BIT:
        def __init__(self, size):
            self.N = size
            self.tree = [0] * (self.N + 1)

        def update(self, idx, delta):
            while idx <= self.N:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

    bit = BIT(max_val)

    # Initialize BIT
    for val in a:
        bit.update(compressed[val], 1)

    # Process queries
    for _ in range(q):
        k = int(next(it))
        if k > 0:
            # Insert k
            bit.update(compressed[k], 1)
        else:
            # Remove |k|-th element
            k = -k
            # Binary search to find the k-th smallest
            left, right = 1, max_val
            res = 0
            while left <= right:
                mid = (left + right) // 2
                cnt = bit.query(mid)
                if cnt >= k:
                    right = mid - 1
                    res = mid
                else:
                    left = mid + 1
            # Remove the found element
            bit.update(res, -1)

    # Find any remaining element
    for i in range(max_val):
        if bit.query(i+1) > 0:
            # Find a value with this compressed index
            for val in sorted_vals:
                if compressed[val] == i+1:
                    print(val)
                    return

    print(0)

if __name__ == "__main__":
    main()
