marks = list(map(int, input().split()))

# We need to assign a marks to subject 1 (1) and b marks to subject 2 (2)
# Sort the marks by value, keeping track of original indices
sorted_marks = sorted(enumerate(marks), key=lambda x: x[1])

result = [0] * n

if b > a:
    # Assign higher marks to subject 2 (we want to maximize S2)
    # Assign the a smallest marks to subject 1
    for i in range(n):
        # If we still need to assign subject 1 marks
        if a > 0:
            # Assign subject 1 to this mark
            result[sorted_marks[i][0]] = 1
            a -= 1
        else:
            # Assign subject 2 to this mark
            result[sorted_marks[i][0]] = 2
elif a > b:
    # Assign higher marks to subject 1 (we want to minimize S2)
    # Assign the b smallest marks to subject 2
    for i in range(n):
        # If we still need to assign subject 2 marks
        if b > 0:
            # Assign subject 2 to this mark
            result[sorted_marks[i][0]] = 2
            b -= 1
        else:
            # Assign subject 1 to this mark
            result[sorted_marks[i][0]] = 1
else:
    # a == b, assign evenly
    # Start with subject 1
    current = 1
    for i in range(n):
        result[sorted_marks[i][0]] = current
        if current == 1 and a > 0:
            a -= 1
        elif current == 2 and b > 0:
            b -= 1
        # Switch to the other subject when we run out
        if a == 0 and current == 1:
            current = 2
        elif b == 0 and current == 2:
            current = 1

print(' '.join(map(str, result)))
