def is_friendship_valid(t1, t2, d):
    """Check if the time difference indicates a friendship."""
    return 0 < t2 - t1 <= d

def main():
    # Read input
    data = input().split()
    n = int(data[0])
    d = int(data[1])

    messages = []
    user_pairs = {}

    for _ in range(n):
        parts = input().split()
        sender = parts[0]
        receiver = parts[1]
        time = int(parts[2])
        messages.append((sender, receiver, time))

    # Store messages in a dictionary by user pairs
    for sender, receiver, time in messages:
        key = frozenset((sender, receiver))
        if key not in user_pairs:
            user_pairs[key] = []
        user_pairs[key].append((sender, receiver, time))

    # Check for friendships
    friends = set()

    for key, pairs in user_pairs.items():
        # For each pair of messages between the same users
        for i in range(len(pairs)):
            for j in range(i + 1, len(pairs)):
                # Check both directions
                s1, r1, t1 = pairs[i]
                s2, r2, t2 = pairs[j]

                # Check if the second message is a response to the first
                if (s1 == s2 and r1 == r2) or (s1 == r2 and r1 == s2):
                    # They are the same pair or opposite direction
                    if s1 == r2 and r1 == s2:
                        # s1 sent to r1 at t1, r2 sent to s2 at t2
                        # This is opposite direction
                        if is_friendship_valid(t1, t2, d):
                            friends.add(frozenset((s1, r2)))
                    elif s1 == r1 and r1 == s2:
                        # They are the same pair (s1-s2)
                        # Actually, this won't happen because we store as frozenset
                        pass

    # Output results
    print(len(friends))
    for pair in friends:
        print(f"{pair[0]} {pair[1]}")

if __name__ == "__main__":
    main()
