def solve():
    n, m = map(int, input().split())
    edges = []
    edges_by_vertex = [[] for _ in range(n + 1)]

    for _ in range(m):
        u, v, c = input().split()
        u, v = int(u), int(v)
        edges.append((u, v, c))
        edges_by_vertex[u].append((v, c))
        edges_by_vertex[v].append((u, c))

    # Function to solve with target color
    def try_color(target):
        flip = [0] * (n + 1)
        reachable = [False] * (n + 1)
        moves = []

        for start in range(1, n + 1):
            if reachable[start]:
                continue

            queue = [start]
            reachable[start] = True
            flip[start] = 0

            while queue:
                u = queue.pop(0)
                for v, c in edges_by_vertex[u]:
                    # current flips
                    current = flip[u] + flip[v]

                    # Determine required flip based on target
                    if target == 0:
                        # want current == 0
                        if current != 0:
                            flip[v] = 1
                            queue.append(v)
                            moves.append(v)
                            reachable[v] = True
                    else:
                        # want current == 1
                        if current != 1:
                            flip[v] = 1
                            queue.append(v)
                            moves.append(v)
                            reachable[v] = True

                    # Set the flip value
                    if flip[u] + flip[v] == target:
                        pass
                    else:
                        flip[v] = 1 - flip[v]
                        queue.append(v)
                        moves.append(v)
                        reachable[v] = True

        # Check if all edges have the target color
        for u, v, c in edges:
            if flip[u] + flip[v] != target:
                return None

        return moves

    red_moves = try_color(0)
    blue_moves = try_color(1)

    if red_moves is not None and blue_moves is not None:
        print(min(len(red_moves), len(blue_moves)))
