import sys

MOD = 10**9 + 7

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    # Read grid
    grid = []
    for i in range(n):
        row = data[idx]; idx += 1
        grid.append(row)

    # dp[x][y] = number of ways to reach cell (x, y)
    # 1-indexed
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[1][1] = 1 if grid[0][0] == '.' else 0

    # How many consecutive rocks we can push from (x, y) in each direction
    # From right: max_right[x][y] = number of consecutive rocks to the right (including itself if it's a rock)
    # From down: max_down[x][y] = number of consecutive rocks below (including itself if it's a rock)

    max_right = [[0] * (m + 1) for _ in range(n + 1)]
    max_down = [[0] * (m + 1) for _ in range(n + 1)]

    # Calculate max_right
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'R':
                max_right[i+1][j+1] = max_right[i+1][j] + 1
            else:
                max_right[i+1][j+1] = 0

    # Calculate max_down
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'R':
                max_down[i+1][j+1] = max_down[i][j+1] + 1
            else:
                max_down[i+1][j+1] = 0

    # Traverse grid in row-major order
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if i == 1 and j == 1:
                continue  # start cell

            # Can we come from above (i-1, j)?
            if i > 1:
                # Check if we can move from (i-1, j) to (i, j)
                # We can move if:
                # - (i, j) is empty, OR
                # - (i, j) has a rock and we can push all consecutive rocks below it

                can_move = False
                if grid[i-1][j-1] == '.':
                    can_move = True
                elif grid[i-1][j-1] == 'R':
                    # Need to check if we can push all consecutive rocks below (i-1, j)
                    if max_down[i][j] > 0:
                        # We can push rocks from (i-1, j) down, but we need to check if the next cell after the last rock is empty
                        # The last rock position is at i + max_down[i][j] - 1
                        last_rock_row = i + max_down[i][j] - 1
                        if last_rock_row + 1 <= n and grid[last_rock_row - 1][j-1] == '.':
                            can_move = True
                        elif last_rock_row + 1 > n:
                            # Out of bounds, can't push
                            can_move = False
                        else:
                            # Check if the next cell can also be pushed (recursive)
                            # Actually, if max_down[i][j] > 0, that means we can push at least one rock
                            # But we need to ensure the chain can continue
                            can_move = max_down[i][j] > 0
                    else:
                        can_move = False

                if can_move:
                    dp[i][j] = (dp[i][j] + dp[i-1][j]) % MOD

            # Can we come from left (i, j-1)?
            if j > 1:
                can_move = False
                if grid[i-1][j-2] == '.':
                    can_move = True
                elif grid[i-1][j-2] == 'R':
                    if max_right[i][j] > 0:
                        # Need to check if we can push all consecutive rocks to the right
                        last_rock_col = j + max_right[i][j] - 1
                        if last_rock_col + 1 <= m and grid[i-1][last_rock_col - 1] == '.':
