def count_max_intervals(a, n):
    """Count intervals where a[i] is the maximum of a in [l, r]."""
    left_max = [-1] * n
    right_max = [-1] * n

    # Find nearest greater or equal to the left
    stack = []
    for i in range(n):
        while stack and a[stack[-1]] < a[i]:
            stack.pop()
        if stack:
            left_max[i] = stack[-1]
        else:
            left_max[i] = -1
        stack.append(i)

    # Find nearest greater to the right
    stack = []
    for i in range(n-1, -1, -1):
        while stack and a[stack[-1]] <= a[i]:
            stack.pop()
        if stack:
            right_max[i] = stack[-1]
        else:
            right_max[i] = n
        stack.append(i)

    count = [0] * n
    for i in range(n):
        count[i] = (i - left_max[i]) * (n - right_max[i])

    return count

def count_min_intervals(b, n):
    """Count intervals where b[i] is the minimum of b in [l, r]."""
