def solve():
    t = int(input())

    # Create memoization table for DP: dp[n][m][k] = min cost to get k squares from n x m bar
    # Note: n and m are up to 30, k is up to 50
    memo = {}  # dictionary for memoization

    def min_cost(n, m, k):
        if k == 0:
            return 0
        if k == n * m:
            return 0

        # Check if already computed
        if (n, m, k) in memo:
            return memo[(n, m, k)]

        min_total_cost = float('inf')

        # Try all possible vertical splits
        for i in range(1, m):
            # Split into (n, i) and (n, m-i)
            # We need to choose how many squares to take from each
            max_from_left = min(k, i * n)
            for x in range(0, max_from_left + 1):
                if x == 0:
                    cost = min_cost(n, m - i, k)
                elif x == k:
                    cost = min_cost(n, i, k)
                else:
                    cost = min_cost(n, i, x) + min_cost(n, m - i, k - x)

                # Cost of breaking is i * n (length = i, width = n)
                total_cost = cost + i * n * i * n
                min_total_cost = min(min_total_cost, total_cost)

        # Try all possible horizontal splits
        for i in range(1, n):
            # Split into (i, m) and (n-i, m)
            max_from_top = min(k, i * m)
            for x in range(0, max_from_top + 1):
                if x == 0:
                    cost = min_cost(i, m, k)
                elif x == k:
                    cost = min_cost(n - i, m, k)
                else:
                    cost = min_cost(i, m, x) + min_cost(n - i, m, k - x)

                # Cost of breaking is m * i (length = m, width = i)
                total_cost = cost + m * i * m * i
                min_total_cost = min(min_total_cost, total_cost)

        memo[(n, m, k)] = min_total_cost
        return min_total_cost

