def solve():
    n, m = map(int, input().split())

    # Use pattern: (3, 4, 3, 4, ...) for the first row
    # Alternate with (4, 3, 4, 3, ...) for subsequent rows

    table = []
    for i in range(n):
        if i % 2 == 0:
            # Even row: pattern (3, 4, 3, 4, ...)
            row = [3 if j % 2 == 0 else 4 for j in range(m)]
        else:
            # Odd row: pattern (4, 3, 4, 3, ...)
            row = [4 if j % 2 == 0 else 3 for j in range(m)]
        table.append(row)

    # Print the table
    for row in table:
        print(' '.join(str(x) for x in row))

solve()
