{"code": "
import sys
input = sys.stdin.read

def solve():
    data = input().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    q = int(data[idx]); idx += 1

    a = list(map(int, data[idx:idx+n]))
    idx += n

    queries = list(map(int, data[idx:idx+q]))

    # Coordinate compression
    values = list(set(a))
    for k in queries:
        if k > 0:
            values.append(k)

    values.sort()
    value_map = {v: i+1 for i, v in enumerate(values)}  # 1-indexed

    # Binary indexed tree (Fenwick Tree)
    class BIT:
        def __init__(self, size):
            self.N = size
            self.tree = [0] * (self.N + 1)

        def update(self, idx, delta):
            while idx <= self.N:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

        def find_kth(self, k):
            idx = 1
            while idx * 2 <= self.N:
                if self.query(idx * 2) >= k:
                    idx *= 2
                else:
                    idx += idx & -idx
            return idx

    bit = BIT(len(values))

    # Initialize with initial multiset
    for val in a:
        bit.update(value_map[val], 1)

    # Process queries
    for k in queries:
        if k > 0:
            bit.update(value_map[k], 1)
        else:
            k_abs = -k
            # Find the k_abs-th smallest element
            val = bit.find_kth(k_abs)
            # Remove one occurrence of this value
            bit.update(val, -1)

    # Output result
    total = bit.query(bit.N)
    if total == 0:
        print(0)
    else:
        # Find any remaining element
        pos = 1
        while pos <= bit.N:
            if bit.query(pos) > bit.query(pos - 1):
                # This position has at least one element
                print(values[pos-1])
                break
            pos += 1

solve()
