def min_moves_to_all_ones_column(n, m, grid):
    """Find minimum moves to make some column all 1s."""

    # For each column, calculate minimum moves
    min_moves = float('inf')

    for target_col in range(m):
        total_moves = 0

        for row in grid:
            # Find closest 1 to target_col
            closest = None
            min_dist = float('inf')

            for pos, value in enumerate(row):
                if value == '1':
                    dist_left = (target_col - pos) % m
                    dist_right = (pos - target_col) % m

                    if dist_left <= dist_right:
                        # Shift left
                        moves = dist_left
                    else:
                        # Shift right
                        moves = dist_right

                    if moves < min_dist:
                        min_dist = moves
                        closest = pos

            # If no 1 found, can't achieve
            if min_dist == float('inf'):
                break

            total_moves += min_dist

        if total_moves < min_moves:
            min_moves = total_moves

    return min_moves if min_moves != float('inf') else -1

