import sys

def is_win(cards, a, b):
    """Check if the configuration (a, b) results in a win"""
    # Columns have b cards each, rows have a cards each
    # Column i has cards at positions i, b+i, 2b+i, ..., (a-1)b+i
    # Check if any column has all 'X'

    for col in range(b):
        # Check column col
        all_x = True
        for row in range(a):
            pos = col + row * b
            if pos >= len(cards) or cards[pos] != 'X':
                all_x = False
                break
        if all_x:
            return True
    return False

def solve():
    data = sys.stdin.read().strip().split()
    t = int(data[0])
    tests = data[1:1+t]

    for test in tests:
        valid_pairs = []

        # Generate all (a, b) pairs where a * b = 12
        for a in range(1, 13):
            if 12 % a == 0:
                b = 12 // a
                if is_win(test, a, b):
                    valid_pairs.append((a, b))

        # Sort by increasing a
        valid_pairs.sort()

        # Format output
        result = [str(len(valid_pairs))] + [f"{a}x{b}" for a, b in valid_pairs]
        print(' '.join(result))

if __name__ == "__main__":
    solve()
"}

