def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_of_list(numbers):
    if not numbers:
        return 0
    result = numbers[0]
    for num in numbers[1:]:
        result = gcd(result, num)
        if result == 1:
            break
    return result

