    n, m, k = map(int, input().split())

    # If it's a 1x1 grid
    if n == 1 and m == 1:
        return 1

    # If it's a 1xn or nx1 grid
    if n == 1 or m == 1:
        if k == 1:
            return 1
        else:  # k == -1
            return pow(2, max(n, m) - 1, MOD)

    # If it's an nxm grid with n>1 and m>1
    if k == 1:
        exponent = (n - 1) * (m - 1)
        return pow(2, exponent, MOD)
    else:  # k == -1
        # Check if n and m have the same parity
        if (n % 2 == m % 2):
            exponent = (n - 1) * (m - 1)
            return pow(2, exponent, MOD)
        else:
            return 0

