# OJ Problem: 894_B. Ralph And His Magic Field
# n, m: grid dimensions (1 ≤ n, m ≤ 10^18)
# k: product of each row and column (either 1 or -1)
# Output: number of ways to fill grid modulo 1000000007

MOD = 1000000007

# Fast exponentiation function
def pow_mod(a, b, mod):
    """Calculate a^b mod mod using modular exponentiation"""
    result = 1
    a = a % mod
    while b > 0:
        if b % 2 == 1:
            result = (result * a) % mod
        a = (a * a) % mod
        b //= 2
    return result

# Read input
n, m, k = map(int, input().split())

if n == 1 and m == 1:
    print(1)
elif n == 1 or m == 1:
    # One dimension is 1, the other > 1
    # For consistency: k^{large_dim} = k
    if k == 1:
        print(1)
    else:
        # k = -1, need large_dim to be odd
        large_dim = m if m > 1 else n
        if large_dim % 2 == 1:
            print(1)
        else:
            print(0)
else:
    # Both dimensions > 1
    if k == 1:
        ans = pow_mod(2, (n-1)*(m-1), MOD)
        print(ans)
    else:
        # k = -1
        if (n % 2 == m % 2):  # same parity
            ans = pow_mod(2, (n-1)*(m-1), MOD)
            print(ans)
        else:
            print(0)
"}

