def validate_username(s):
    """Validate username format"""
    if len(s) < 1 or len(s) > 16:
        return False
    if s[0] == '_':
        return False
    if ' ' in s:
        return False

    for ch in s:
        if not (ch.isalnum() or ch == '_'):
            return False

    return True

def validate_hostname(s):
    """Validate hostname format"""
    if len(s) < 1 or len(s) > 32:
        return False
    words = s.split('.')

    # Each word must be valid (same as username)
    for word in words:
        if len(word) < 1 or len(word) > 16:
            return False
        if not validate_username(word):
            return False

    return True

def validate_resource(s):
    """Validate optional resource format"""
    if len(s) < 1 or len(s) > 16:
        return False
    if s[0] != '[' or s[-1] != ']':
        return False

    # Remove brackets
    content = s[1:-1]

    if ' ' in content or '.' in content:
        return False

    for ch in content:
        if not (ch.isalnum() or ch == '_'):
            return False

    return True

def main():
    s = input().strip()

    at_index = s.find('@')
    if at_index == -1:
        print("NO")
        return

    username = s[:at_index]
    rest = s[at_index+1:]

    if not validate_username(username):
        print("NO")
        return

    slash_index = rest.find('/')
    if slash_index != -1:
        hostname = rest[:slash_index]
        resource = rest[slash_index+1:]

