    for i in range(n):
        d, s = map(int, input().split())
        deg[i] = d
        xor_sum[i] = s

    # Find vertices with degree 0 - they have no edges
    isolated = []
    for i in range(n):
        if deg[i] == 0:
            isolated.append(i)

    # Build result
    edges = []
    used = [False] * n

    for v in range(n):
        # Skip isolated vertices
        if v in isolated:
            continue

        # Skip vertices we've already used
        if used[v]:
            continue

        # If degree is 1, we need to find the vertex that matches
        if deg[v] == 1:
            # The vertex v should be adjacent to xor_sum[v]
            neighbor = xor_sum[v]

            # Check if neighbor is valid
            if 0 <= neighbor < n and not used[neighbor]:
                edges.append((v, neighbor))
