    deg = [-1] * n
    xor_sum = [-1] * n

    # Read input
    for i in range(n):
        d, s = map(int, input().split())
        deg[i] = d
        xor_sum[i] = s

    # Build adjacency list
    adj = [[] for _ in range(n)]

    # For each vertex, try to find matching neighbors
    for v in range(n):
        # Skip if already used
        if len(adj[v]) == deg[v]:
            continue

        # Try to find a matching neighbor
        for candidate in range(n):
            if candidate == v:
                continue

            # Check if candidate can be a neighbor
            if deg[candidate] == 1:
                # Degree 1 vertex must be adjacent to v
                # Check if v is in candidate's XOR sum
                if xor_sum[candidate] == v:
                    adj[v].append(candidate)
                    adj[candidate].append(v)
                    break
            elif deg[candidate] > 1:
                # Degree > 1, check if v is in candidate's XOR sum
                if v in adj[candidate]:
                    continue

                # Check if the XOR sum with current neighbors matches
                xor_with_neighbors = 0
                for neighbor in adj[candidate]:
                    xor_with_neighbors ^= neighbor

                if xor_with_neighbors == xor_sum[candidate] ^ v:
                    adj[v].append(candidate)
                    adj[candidate].append(v)
                    break

    # Output
