# Dictionary to store for each student ID, the ID of the person behind them
behind = {}

for _ in range(n):
    a, b = map(int, input().split())
    front[a] = b
    behind[b] = a

# Build adjacency list
adj = {}
for student in range(1, n + 1):
    adj[student] = []

# Add edges based on front and behind relationships
for student in range(1, n + 1):
    # If there's someone in front, add that person as a predecessor
    if student in front and front[student] != 0:
        adj[front[student]].append(student)

    # If there's someone behind, add that person as a successor
    if student in behind and behind[student] != 0:
        adj[student].append(behind[student])

# Topological sort using Kahn's algorithm
in_degree = {i: 0 for i in range(1, n + 1)}
for src in adj:
    for dst in adj[src]:
        in_degree[dst] += 1

queue = [i for i in range(1, n + 1) if in_degree[i] == 0]
result = []

while queue:
    current = queue.pop(0)
    result.append(current)

    for neighbor in adj[current]:
        in_degree[neighbor] -= 1
        if in_degree[neighbor] == 0:
            queue.append(neighbor)

print(' '.join(map(str, result)))
