import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    data = list(map(int, data))
    n = data[0]
    a = data[1:1+n]
    b = data[1+n:1+2*n]

    # Find left boundaries for max in a
    left_a = [-1] * n
    stack = []
    for i in range(n):
        while stack and a[stack[-1]] < a[i]:
            stack.pop()
        if stack:
            left_a[i] = stack[-1]
        else:
            left_a[i] = -1
        stack.append(i)

    # Find right boundaries for max in a
    right_a = [n] * n
    stack = []
    for i in range(n-1, -1, -1):
        while stack and a[stack[-1]] <= a[i]:
            stack.pop()
        if stack:
            right_a[i] = stack[-1]
        else:
            right_a[i] = n
        stack.append(i)

    # Find left boundaries for min in b
    left_b = [-1] * n
    stack = []
    for i in range(n):
        while stack and b[stack[-1]] > b[i]:
            stack.pop()
        if stack:
            left_b[i] = stack[-1]
        else:
            left_b[i] = -1
        stack.append(i)

    # Find right boundaries for min in b
    right_b = [n] * n
    stack = []
    for i in range(n-1, -1, -1):
        while stack and b[stack[-1]] >= b[i]:
            stack.pop()
        if stack:
            right_b[i] = stack[-1]
        else:
            right_b[i] = n
        stack.append(i)

    ans = 0
    for i in range(n):
        if a[i] != b[i]:
            continue

        l_left = max(left_a[i] + 1, left_b[i] + 1)
        r_right = min(right_a[i] - 1, right_b[i] - 1)

        if l_left <= r_right:
            ans += r_right - l_left + 1

    print(ans)

if __name__ == "__main__":
    solve()
