def solve():
    t = int(input())
    results = []

    def dp(a, b, k):
        """Minimum cost to break a a×b chocolate bar to get exactly k squares"""
        if (a, b, k) in memo:
            return memo[(a, b, k)]

        if k == 0 or k == a * b:
            memo[(a, b, k)] = 0
            return 0

        # Work with smaller dimension first
        if a > b:
            a, b = b, a

        min_cost = float('inf')

        # Try all horizontal breaks
        for i in range(1, a):
            cost = a * a
            for k1 in range(k + 1):
                k2 = k - k1
                cost += dp(i, b, k1)
                cost += dp(a - i, b, k2)
                min_cost = min(min_cost, cost)

        # Try all vertical breaks
        for j in range(1, b):
            cost = b * b
            for k1 in range(k + 1):
                k2 = k - k1
                cost += dp(a, j, k1)
                cost += dp(a, b - j, k2)
                min_cost = min(min_cost, cost)

        memo[(a, b, k)] = min_cost
        return min_cost

    memo = {}

    for _ in range(t):
        n, m, k = map(int, input().split())
        results.append(str(dp(n, m, k)))

    print('\n'.join(results))

solve()
