answer = 0

# For each vertex i (0-indexed)
for i in range(n - 1):
    val = a[i]
    next_val = a[i + 1]

    if val < next_val:
        # val is left endpoint when next_val not in [l, r]
        left = (val - 1) * (n - next_val)
    else:
        left = 0

    if val > next_val:
        # next_val is right endpoint when val not in [l, r]
        right = (next_val - 1) * (n - val)
    else:
        right = 0

    answer += left + right

# Handle vertex n-1
if a[n - 1] > a[n - 2]:
    # Last vertex is right endpoint
    answer += (a[n - 2] - 1) * (n - a[n - 1])

