import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    results = []

    for _ in range(t):
        n = int(data[idx]); m = int(data[idx+1]); k = int(data[idx+2])
        idx += 3

        h = []
        for _ in range(n):
            h.append(int(data[idx]))
            idx += 1

        possible = True

        # Start at column 1
        for i in range(n - 1):
            # If we can move directly to column i+1
            if abs(h[i] - h[i+1]) <= k:
                pass  # No adjustment needed
            else:
                # Need to adjust one of the columns
                # If h[i] > h[i+1], we can lower column i
                if h[i] > h[i+1]:
                    # Lower column i to match column i+1
                    h[i] = h[i+1]
                else:
                    # Need to raise column i to at least h[i+1] - k
                    needed = max(0, h[i+1] - k - h[i])
                    if needed > m:
                        possible = False
                        break
                    m -= needed
                    h[i] += needed

        if possible:
            results.append("YES")
        else:
            results.append("NO")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

