    for _ in range(n):
        names.append(input().strip())

    # For each letter, keep track of the best (longest) name
    best_start = {chr(ord('a') + i): 0 for i in range(26)}
    best_end = {chr(ord('a') + i): 0 for i in range(26)}

    # Also keep track of the best name that starts and ends with each letter
    best_cycle = {chr(ord('a') + i): 0 for i in range(26)}

    # dp[start][end] = maximum dynasty length starting with letter 'start' and ending with letter 'end'
    dp = [[0 for _ in range(26)] for _ in range(26)]

    # Initially, no dynasty
    for i in range(26):
        for j in range(26):
            dp[i][j] = 0

    # Process each name
    for name in names:
        s, t = name[0], name[-1]
        length = len(name)

        # Update best_start and best_end
        if length > best_start[s]:
            best_start[s] = length
        if length > best_end[t]:
            best_end[t] = length

        # Update best_cycle (longest cycle that starts and ends with this letter)
        if length > best_cycle[s]:
            best_cycle[s] = length
        if length > best_cycle[t]:
            best_cycle[t] = length

        # Try to extend existing sequences
        for i in range(26):
            for j in range(26):
                if dp[i][j]:
                    # Can we extend from i to j using this name (s -> t) if j == s?
                    if j == s:
                        new_length = dp[i][j] + length
                        if new_length > dp[i][t]:
                            dp[i][t] = new_length
                    # Can we extend from i to j using this name if i == t and we need to form a cycle?
                    if i == t and j == s:
                        new_cycle_length = dp[i][j] + length
                        if new_cycle_length > best_cycle[s]:
                            best_cycle[s] = new_cycle_length

    # Find the maximum cycle
    max_cycle = max(best_cycle.values())

