import sys
import array

def FenwickTree(n):
    """1-indexed"""
    data = array.array('i', [0] * (n + 2))  # 1..n
    def add(i, delta):
        i += 1  # 1-indexed
        while i <= n + 1:
            data[i] += delta
            i += i & -i
    def get_sum(i):
        i += 1
        res = 0
        while i > 0:
            res += data[i]
            i -= i & -i
        return res
    return add, get_sum

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    q = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    queries = [int(next(it)) for _ in range(q)]

    ft_add, ft_get_sum = FenwickTree(n)

    for val in a:
        ft_add(val, 1)

    for k in queries:
        if k > 0:
            ft_add(k, 1)
        else:
            k = -k
            lo, hi = 1, n
            ans = -1
            while lo <= hi:
                mid = (lo + hi) // 2
                s = ft_get_sum(mid)
                if s >= k:
                    ans = mid
                    hi = mid - 1
                else:
                    lo = mid + 1
            if ans == -1:
                break
            ft_add(ans, -1)

    # Find any remaining element
    for i in range(1, n + 1):
        if ft_get_sum(i) > 0:
            sys.stdout.write(str(i) + b'
')
            return
    sys.stdout.write(b'0')

if __name__ == "__main__":
    solve()
