import sys

class FenwickTree:
    """1-indexed"""
    def __init__(self, n):
        self.data = [0] * (n + 2)  # 1..n
    def add(self, i, delta):
        i += 1  # 1-indexed
        while i <= n + 1:
            self.data[i] += delta
            i += i & -i
    def get_sum(self, i):
        i += 1
        res = 0
        while i > 0:
            res += self.data[i]
            i -= i & -i
        return res

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    q = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    queries = [int(next(it)) for _ in range(q)]

    ft_add = FenwickTree(n).add
