def compute_grundy(s):
    n = len(s)
    grundy = [0] * (n + 1)  # grundy[i] for string of length i

    # For strings of length 1, there are no valid moves
    # For strings of length 2, no valid moves
    # For strings of length 3, check if s[0] == s[2] (indices 0,1,2)

    # We'll use a dictionary to memoize results for substrings
    memo = {}

    def get_grundy(subs):
        # subs is a tuple of characters
        if subs in memo:
            return memo[subs]
        n = len(subs)
        if n == 0:
            return 0
        if n == 1:
            return 0
        if n == 2:
            return 0

        reachable = set()
        for i in range(1, n):  # Cut at position i (1-indexed)
            # Check if there are symmetric equal characters
            found = False
            for l in range(1, i):
                if i - l - 1 >= 0 and i + l < n:
                    if subs[i - l - 1] == subs[i + l]:
                        found = True
                        break
            if found:
                left = subs[:i]  # positions 1..i-1
                right = subs[i+1:]  # positions i+1..n
                gr_left = get_grundy(left)
                gr_right = get_grundy(right)
                reachable.add(gr_left ^ gr_right)

        # Compute mex (minimum excludant)
        mex = 0
        while mex in reachable:
            mex += 1

        memo[subs] = mex
        return mex

    # Compute grundy for all strings of length 1..n
    for length in range(1, n + 1):
        subs = tuple(s[:length])
        grundy[length] = get_grundy(subs)

    return grundy[n], grundy[n]  # (grundy number, 0 if first player wins)

