import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        a = int(data[idx]); idx += 1
        b = int(data[idx]); idx += 1
        adj[a].append(b)
        adj[b].append(a)

    # visited array
    visited = [False] * (n + 1)

    def dfs(start):
        stack = [(start, False)]
        edges_count = 0

        while stack:
            node, processed = stack.pop()
            if processed:
                # When we process a node again, it's through an edge
                # Count this edge
                edges_count += 1
            else:
                if visited[node]:
                    continue
                visited[node] = True
                stack.append((node, True))

                # Add neighbors
                for neighbor in adj[node]:
                    stack.append((neighbor, False))
        return edges_count

    total_removals = 0
    for i in range(1, n + 1):
        if not visited[i]:
            edges = dfs(i)
            if edges % 2 == 1:
                total_removals += 1

    print(total_removals)

if __name__ == "__main__":
    solve()
