import sys

def find_valleys(arr):
    """Find indices where price decreases then increases"""
    valleys = []
    i = 1
    while i < len(arr) - 1:
        if arr[i] < arr[i-1] and arr[i] < arr[i+1]:
            # Check if this is the first valley
            if i == 1 or arr[i] < arr[i-1]:
                valleys.append(i)
        i += 1
    return valleys

def find_peaks(arr):
    """Find indices where price increases then decreases"""
    peaks = []
    i = 1
    while i < len(arr) - 1:
        if arr[i] > arr[i-1] and arr[i] > arr[i+1]:
            # Check if this is the first peak
            if i == 1 or arr[i] > arr[i-1]:
                peaks.append(i)
        i += 1
    return peaks

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    prices = list(map(int, data[1:1+n]))

    valleys = find_valleys(prices)
    peaks = find_peaks(prices)

    # Buy at each valley, sell at each peak
    buy_cost = sum(prices[i] for i in valleys)
    sell_revenue = sum(prices[i] for i in peaks)

    print(sell_revenue - buy_cost)

if __name__ == "__main__":
    solve()
