        s = input().strip()
        string_positions[s] = list(range(len(t) - len(s) + 1))

    result = 0

    # For each string and its positions
    for s, positions in string_positions.items():
        for pos in positions:
            # Find how many strings can start at pos + len(s)
            for end in range(pos + len(s), len(t)):
                substr = t[pos + len(s):end + 1]
                if substr in string_positions:
                    result += 1

    print(result)

