n, k = map(int, input().split())
books = list(map(int, input().split()))
problems = list(map(int, input().split()))

# Calculate prefix sums of differences (math - economics)
diff = [0] * n
for i in range(n):
    if books[i] == 1:
        diff[i] = problems[i]
    elif books[i] == 2:
        diff[i] = -problems[i]

prefix = [0] * (n + 1)
for i in range(n):
    prefix[i + 1] = prefix[i] + diff[i]

q = int(input())
results = []

for _ in range(q):
    L, R = map(int, input().split())
    count = 0

    # For each possible start point l in [L, R]
    for l in range(L, R + 1):
        # We need prefix[r] - prefix[l-1] = k for r in [l, R]
        # So we need prefix[r] = prefix[l-1] + k

        target = prefix[l - 1] + k

        # Count how many times target appears in prefix[l...R]
        freq = {}
        for r in range(l, R + 1):
            freq[prefix[r]] = freq.get(prefix[r], 0) + 1

        count += freq.get(target, 0)

    results.append(count)

for res in results:
    print(res)
