def is_winning(s, a, b):
    """Check if there's a column with all 'X' for grid of size a x b"""
    # Check each column
    for col in range(b):
        all_x = True
        for row in range(a):
            pos = col + row * b
            if s[pos] != 'X':
                all_x = False
                break
        if all_x:
            return True
    return False


def solve():
    t = int(input())

    for _ in range(t):
        s = input().strip()

        # Find all factor pairs (a, b) such that a * b = 12
        factors = []
        for a in range(1, 13):
            if 12 % a == 0:
                b = 12 // a
                factors.append((a, b))

        result = []
        for a, b in factors:
            if is_winning(s, a, b):
                result.append(f"{a}x{b}")

        print(f"{len(result)} {' '.join(result)}")

solve()
