# Read the input
a = input().strip()

# Find the first '0' that appears after some '1's
def solve_binary(a):
    # Find the first index where a '0' appears after some '1's
    first_zero_after_one = -1
    for i in range(len(a)):
        if a[i] == '0':
            # Check if there are any '1's before this '0'
            if i > 0 and a[i-1] == '1':
                first_zero_after_one = i
                break

    # If found, delete that '0'
    if first_zero_after_one != -1:
        return a[:first_zero_after_one] + a[first_zero_after_one+1:]

    # If not found (all '0's are at the beginning), delete the last '0'
    last_zero_index = -1
    for i in range(len(a)):
        if a[i] == '0':
            last_zero_index = i

    if last_zero_index != -1:
        return a[:last_zero_index] + a[last_zero_index+1:]

# Get the solution
solution = solve_binary(a)

# Output without leading zeros
print(solution.lstrip('0') or '0')
